SELECT analytics_expense_facts.month, SUM(analytics_expense_facts.expense_amount) AS expense_amount FROM analytics_expense_facts WHERE analytics_expense_facts.year = 2022 AND analytics_expense_facts.department = 'department_06' AND analytics_expense_facts.cost_center = 'cc_051' AND analytics_expense_facts.expense_category = 'expense_03' GROUP BY analytics_expense_facts.month ORDER BY analytics_expense_facts.month ASC LIMIT 12
